const LABELS={date:'fecha',people:'número de personas',activities:'actividades',lodging:'alojamiento',name:'nombre',contact:'contacto'};
const REQUIRED={despedida:['name','contact','date','people','activities'],amigos:['name','contact','date','people','activities'],familia:['name','contact','date','people','activities'],empresa:['name','contact','date','people','activities'],escolar:['name','contact','date','people','activities'],solo_actividad:['name','contact','date','people','activities'],pack_alojamiento:['name','contact','date','people','activities','lodging'],revision:['name','contact']};
const clean=v=>String(v??'').trim().replace(/\s+/g,' ');
const normEmail=v=>clean(v).toLowerCase();
const normPhone=v=>{const s=clean(v);if(!s)return '';return s.startsWith('+')?'+'+s.replace(/\D/g,''):s.replace(/\D/g,'');};
const classify=raw=>{const text=[raw.group_type,raw.message,raw.activities,raw.lodging].map(clean).join(' ').toLowerCase();const rules=[['despedida',/despedid/],['empresa',/empresa|team\s?building|corporativ/],['escolar',/escolar|colegio|instituto|alumn/],['familia',/familia|niñ|hijos?/],['pack_alojamiento',/alojamiento|hotel|hostal|casa rural|pack/],['solo_actividad',/solo actividad|actividad suelta|sin alojamiento/],['amigos',/amigos?|grupo/]];for(const [cat,rx] of rules)if(rx.test(text))return cat;return 'revision';};
const input=$input.all().map(i=>i.json.body??i.json);
return input.map(raw=>{
  const contact=clean(raw.email)||clean(raw.phone);
  if(!clean(raw.event_id)) return {json:{ok:false,status:'validation_failed',errors:['missing_event_id'],autonomous_send:false}};
  if(!clean(raw.name)||!contact) return {json:{ok:false,status:'validation_failed',errors:['missing_name_or_contact'],autonomous_send:false}};
  const category=classify(raw);
  const view={name:clean(raw.name),contact,date:clean(raw.date),people:clean(raw.people),activities:clean(raw.activities),lodging:clean(raw.lodging)};
  const missing=(REQUIRED[category]||REQUIRED.revision).filter(k=>!view[k]);
  const summary=[`Tipo: ${category}`,`Nombre: ${view.name||'N/D'}`,`Contacto: ${contact||'N/D'}`,`Fecha: ${view.date||'N/D'}`,`Personas: ${view.people||'N/D'}`,`Actividades: ${view.activities||'N/D'}`,`Alojamiento: ${view.lodging||'N/D'}`,`Faltan: ${missing.length?missing.map(x=>LABELS[x]||x).join(', '):'nada crítico'}`].join('\n');
  const prefix=clean(raw.name)||'Hola';
  const reply=missing.length?`${prefix}, gracias por contactar con Huescaventura. Para orientarte mejor sobre ${category}, antes necesitamos confirmar: ${missing.map(x=>LABELS[x]||x).join(', ')}. Este mensaje es un borrador para revisión humana y no se ha enviado.`:`${prefix}, gracias por contactar con Huescaventura. Tenemos la información básica para revisar tu solicitud de ${category}. Prepararemos la opción más adecuada y confirmaremos disponibilidad y condiciones antes de responderte. Este mensaje es un borrador para revisión humana y no se ha enviado.`;
  return {json:{ok:true,status:'prepared_for_human_review',event_id:clean(raw.event_id),identity:{email:normEmail(raw.email),phone:normPhone(raw.phone)},category,classification_review_required:category==='revision',missing_fields:missing,summary,reply_draft:reply,next_step:category==='revision'?'manual_classification_review':(missing.length?'request_missing_data':'human_review_quote_or_availability'),followup:{status:'pending_human_decision',autonomous_send:false},persistence_note:'Demo importable: deduplication/idempotency persistence must be bound to Airtable/Sheet/DB in client environment.'}};
});
